<?php
$search=scalar_value($_GET,'search');$visibility=scalar_value($_GET,'visibility');$where=[];$params=[];
if($search!==''){$where[]='(p.name LIKE ? OR u.name LIKE ? OR r.comment LIKE ?)';$params=array_fill(0,3,'%'.$search.'%');}
if(in_array($visibility,['visible','hidden'],true)){$where[]='r.is_hidden=?';$params[]=$visibility==='hidden'?1:0;}
if($visibility==='visible')$where[]='r.customer_deleted=0';
$reviews=all('SELECT r.*,p.name product_name,u.name customer_name,a.name moderator_name FROM reviews r JOIN products p ON p.id=r.product_id JOIN users u ON u.id=r.user_id LEFT JOIN users a ON a.id=r.moderated_by_admin_id'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY r.id DESC',$params);
?>
<form method="get" class="inline-form"><input type="hidden" name="page" value="admin"><input type="hidden" name="section" value="reviews"><label>Product, customer or review<input name="search" value="<?=e($search)?>" maxlength="100"></label><label>Visibility<select name="visibility"><option value="">All</option><option value="visible" <?=$visibility==='visible'?'selected':''?>>Visible</option><option value="hidden" <?=$visibility==='hidden'?'selected':''?>>Hidden</option></select></label><button class="btn btn-outline">Search</button></form>
<section class="admin-card"><h2>Review moderation</h2><?php if(!$reviews):?><p>No reviews found.</p><?php endif;foreach($reviews as $r):?><article class="address-card"><h3><?=e($r['product_name'])?> · <?=$r['rating']?> / 5</h3><p><?=e($r['customer_name'])?> · <?=$r['customer_deleted']?'Removed by customer':($r['is_hidden']?'Hidden':'Visible')?></p><p><?=e($r['comment'])?></p><?php if($r['moderated_at']):?><small>Last moderation: <?=e($r['moderator_name']??'Former administrator')?> · <?=e($r['moderated_at'])?></small><?php endif;?><form method="post"><?php admin_hidden('admin_review_moderate','reviews',(int)$r['id']);?><input type="hidden" name="hidden" value="<?=$r['is_hidden']?0:1?>"><button class="btn btn-outline"><?=$r['is_hidden']?'Restore review':'Hide review'?></button></form></article><?php endforeach;?></section>
